CREATE TABLE "SiteSettings" (
  "id" TEXT NOT NULL DEFAULT 'global', "storeNameAr" TEXT NOT NULL DEFAULT 'Ever Green لتحف وديكورات الحدائق', "storeNameEn" TEXT NOT NULL DEFAULT 'EVER GREEN Garden Ornaments & Outdoor Decor', "logoUrl" TEXT, "faviconUrl" TEXT, "defaultCurrency" TEXT NOT NULL DEFAULT 'ILS', "contactEmail" TEXT NOT NULL DEFAULT 'info@evergreen.ps', "contactPhone" TEXT NOT NULL DEFAULT '0559401774', "contactWhatsApp" TEXT, "addressAr" TEXT NOT NULL DEFAULT 'فلسطين', "addressEn" TEXT NOT NULL DEFAULT 'Palestine', "googleMapsUrl" TEXT, "businessHoursAr" TEXT, "businessHoursEn" TEXT, "footerAboutAr" TEXT NOT NULL DEFAULT 'Ever Green وجهتك المختارة لتحف وديكورات الحدائق، النوافير، الأصص والإكسسوارات الخارجية.', "footerAboutEn" TEXT NOT NULL DEFAULT 'Ever Green is your carefully selected destination for garden ornaments, outdoor decor, fountains, planters, and accessories.', "copyrightTextAr" TEXT NOT NULL DEFAULT 'جميع الحقوق محفوظة © Ever Green لتحف وديكورات الحدائق', "copyrightTextEn" TEXT NOT NULL DEFAULT 'All rights reserved © Ever Green Garden Ornaments & Outdoor Decor', "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "SiteSettings_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "SocialLink" ("id" TEXT NOT NULL, "platform" TEXT NOT NULL, "url" TEXT NOT NULL, "icon" TEXT, "isActive" BOOLEAN NOT NULL DEFAULT true, "order" INTEGER NOT NULL DEFAULT 0, CONSTRAINT "SocialLink_pkey" PRIMARY KEY ("id"));
CREATE TABLE "HomepageSection" ("id" TEXT NOT NULL, "key" TEXT NOT NULL, "type" TEXT NOT NULL, "titleAr" TEXT, "titleEn" TEXT, "subtitleAr" TEXT, "subtitleEn" TEXT, "contentAr" TEXT, "contentEn" TEXT, "imageAr" TEXT, "imageEn" TEXT, "ctaTextAr" TEXT, "ctaTextEn" TEXT, "ctaLink" TEXT, "isActive" BOOLEAN NOT NULL DEFAULT true, "order" INTEGER NOT NULL DEFAULT 0, CONSTRAINT "HomepageSection_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "HomepageSection_key_key" ON "HomepageSection"("key");
CREATE TABLE "Banner" ("id" TEXT NOT NULL, "titleAr" TEXT, "titleEn" TEXT, "subtitleAr" TEXT, "subtitleEn" TEXT, "imageUrl" TEXT NOT NULL, "mobileImageUrl" TEXT, "ctaTextAr" TEXT, "ctaTextEn" TEXT, "ctaUrl" TEXT, "isActive" BOOLEAN NOT NULL DEFAULT true, "startDate" TIMESTAMP(3), "endDate" TIMESTAMP(3), "order" INTEGER NOT NULL DEFAULT 0, CONSTRAINT "Banner_pkey" PRIMARY KEY ("id"));
CREATE TABLE "StorePolicy" ("id" TEXT NOT NULL, "slug" TEXT NOT NULL, "titleAr" TEXT NOT NULL, "titleEn" TEXT NOT NULL, "contentAr" TEXT NOT NULL, "contentEn" TEXT NOT NULL, "isActive" BOOLEAN NOT NULL DEFAULT true, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "StorePolicy_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "StorePolicy_slug_key" ON "StorePolicy"("slug");
CREATE TABLE "NavigationItem" ("id" TEXT NOT NULL, "labelAr" TEXT NOT NULL, "labelEn" TEXT NOT NULL, "url" TEXT NOT NULL, "order" INTEGER NOT NULL DEFAULT 0, "isActive" BOOLEAN NOT NULL DEFAULT true, "parentId" TEXT, CONSTRAINT "NavigationItem_pkey" PRIMARY KEY ("id"));
ALTER TABLE "NavigationItem" ADD CONSTRAINT "NavigationItem_parentId_fkey" FOREIGN KEY ("parentId") REFERENCES "NavigationItem"("id") ON DELETE SET NULL ON UPDATE CASCADE;
CREATE TABLE "PageContent" ("id" TEXT NOT NULL, "slug" TEXT NOT NULL, "titleAr" TEXT NOT NULL, "titleEn" TEXT NOT NULL, "contentAr" TEXT NOT NULL, "contentEn" TEXT NOT NULL, "images" TEXT[] NOT NULL, "isActive" BOOLEAN NOT NULL DEFAULT true, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "PageContent_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "PageContent_slug_key" ON "PageContent"("slug");
